package tv.vela.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import java.lang.reflect.*;

/** Grouping, selection, XMLTV matching/rollback and bounded native UI on an isolated emulator. */
public final class AndroidTvRedesignTest extends Instrumentation {
 private void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 private Object field(Object o,String name)throws Exception{if(o instanceof ScreenActivity)o=((ScreenActivity)o).screen;for(Class<?> type=o.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
 private void ui(Runnable action){runOnMainSync(action);waitForIdleSync();}
 private void restore(SharedPreferences p,Map<String,?> before){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> item:before.entrySet()){Object v=item.getValue();if(v instanceof String)e.putString(item.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(item.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(item.getKey(),(Long)v);else if(v instanceof Integer)e.putInt(item.getKey(),(Integer)v);else if(v instanceof Set)e.putStringSet(item.getKey(),new HashSet<>((Set<String>)v));}e.commit();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences prefs=LiveTvData.prefs(c),epg=c.getSharedPreferences("xmltv",0);Map<String,?> before=new HashMap<>(prefs.getAll()),epgBefore=new HashMap<>(epg.getAll());String source="redesign-owned";TvCatalogCache cache=new TvCatalogCache(c);try{
  check(Build.MODEL.contains("sdk")||Build.FINGERPRINT.contains("generic"),"Isolated emulator required");
  List<String> url=Collections.singletonList("https://example.invalid/live.m3u8");
  try(TvCatalogCache.Writer writer=cache.writer(source)){for(int n=1;n<=25;n++)for(String q:new String[]{"SD","HD","FHD"})writer.add(new LiveTvData.Channel(n+q,"ES| Canal "+n+" "+q,"General","",url),false);writer.add(new LiveTvData.Channel("uk","UK| Canal 1 FHD","General","",url),false);writer.add(new LiveTvData.Channel("plus","ES| Canal 1 +1 FHD","General","",url),false);writer.add(new LiveTvData.Channel("region","ES| Canal 1 Canarias FHD","General","",url),false);writer.commit("{}");}
  TvCatalogCache.Page first=cache.page(source,null,"",null,0);check(first.total==28&&first.channels.size()==12,"Quality duplicates or distinct country/region/time-shift grouped incorrectly");LiveTvData.Channel ch=first.channels.get(0);check(ch.id.equals("1FHD")&&ch.variants.size()==3,"Automatic FHD or bounded variant list incorrect");
  TvChannelNames.prefer(c,source,ch.variants.get(2));check(cache.page(source,null,"",null,0).channels.get(0).id.equals("1SD"),"Chosen quality not remembered");check(cache.page(source,null,"",null,2).channels.size()==4,"Last grouped page incorrect");Set<String> old=new HashSet<>(Collections.singletonList("1HD"));TvCatalogCache.Page fav=cache.page(source,null,"",old,0);check(fav.total==1&&TvChannelNames.favorite(fav.channels.get(0),old),"An existing HD favorite was lost after grouping");
  try(TvCatalogCache.Writer writer=cache.writer(source+"-m3u")){for(String quality:new String[]{"SD","HD","FHD"})writer.add(new LiveTvData.Channel("same-tvg","La 1 "+quality,"General","",url),true);writer.commit("{}");}LiveTvData.Channel merged=cache.page(source+"-m3u",null,"",null,0).channels.get(0);check(merged.variants.size()==3&&TvChannelNames.quality(merged.name).equals("FHD"),"Same-ID M3U qualities were lost");cache.remove(source+"-m3u");
  check(TvChannelNames.display("ES| La 1 FHD").equals("La 1")&&TvChannelNames.display("Canal 10801 FHD").equals("Canal 10801"),"Channel numbers mistaken for resolutions");
  check(TvChannelNames.display("ES| La 1 HD (VDF)").equals("La 1")&&TvChannelNames.quality("ES| La 1 HD (VDF)").equals("HD"),"VDF transport label not grouped");check(TvChannelNames.display("ES_Antena 3(ZAP) FHD").equals("Antena 3"),"ZAP transport label created another channel");check(TvChannelNames.display("[ES] La 1 UHD").equals("La 1")&&TvChannelNames.display("ES_La 2 HD").equals("La 2")&&TvChannelNames.country("[ES] La 1").equals("ES"),"Bracket/underscore provider prefixes not recognized");
  long now=System.currentTimeMillis()/1000;java.text.SimpleDateFormat date=new java.text.SimpleDateFormat("yyyyMMddHHmmss Z",Locale.ROOT);date.setTimeZone(TimeZone.getTimeZone("UTC"));String start=date.format(new Date((now-3600)*1000)),stop=date.format(new Date((now+3600)*1000));
  String xml="<tv><channel id='La 1 HD'><display-name>La 1</display-name><display-name>La1.TV</display-name></channel><programme channel='La 1 HD' start='"+start+"' stop='"+stop+"'><title>Programa &amp; especial</title></programme></tv>";
  XmlTvGuide guide=new XmlTvGuide(c);guide.importGuide(new ByteArrayInputStream(xml.getBytes("UTF-8")),"owned-test",now);LiveTvData.Channel one=new LiveTvData.Channel("one","ES| La 1 FHD","General","",url,"","","","","La1.TV");Map<String,LiveTvData.Guide> match=guide.read(Collections.singletonList(one),now);check(match.size()==1&&match.get("one").current(now).title.equals("Programa & especial"),"XMLTV ID/name/entity match failed");
  LiveTvData.Channel foreign=new LiveTvData.Channel("foreign","UK| La 1 FHD","General","",url,"","","","","unknown");check(guide.read(Collections.singletonList(foreign),now).isEmpty(),"Foreign channel received a Spanish name-only match");
  boolean rejected=false;try{guide.importGuide(new ByteArrayInputStream("<!DOCTYPE tv [<!ENTITY x SYSTEM 'file:///private'>]><tv/>".getBytes("UTF-8")),"bad",now);}catch(Exception expected){rejected=true;}check(rejected&&guide.read(Collections.singletonList(one),now).size()==1,"Unsafe XML or incomplete import replaced valid guide");
  File real=new File(c.getExternalFilesDir(null),"redesign-xmltv.xml");if(real.exists()){long at=SystemClock.elapsedRealtime();try(InputStream in=new FileInputStream(real)){guide.importGuide(in,LiveTvData.hash(XmlTvGuide.DEFAULT_URL),now);}result.putLong("real_xmltv_import_ms",SystemClock.elapsedRealtime()-at);check(guide.read(Collections.singletonList(one),now).containsKey("one"),"Actual dobleM guide did not match La 1");check(LiveTvData.https(guide.logo(one)),"Actual XMLTV original fallback logo missing");}
  result.putString("result","PASS disk grouping, country/region/+1 separation, FHD default and saved SD, favorite migration, bounded grouped pages, conservative name/ID XMLTV matching, entities/DOCTYPE rejection, rollback and real dobleM file when supplied.");
 }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}finally{cache.remove(source);restore(prefs,before);restore(epg,epgBefore);}finish(result.containsKey("error")?1:-1,result);}
}
